// Validates the incoming order request. No external calls, no writes.
// Prices and delivery fees supplied by the caller are never used.
const MAX_ITEMS = 50;
const MAX_QTY = 100;
const LIMITS = { customer_id: 64, restaurant_id: 64, menu_item_id: 64, delivery_address: 300, area_name: 100, payment_method: 50, variant: 50 };

const raw = $input.first().json || {};
let body = raw.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = null; }
}

const errors = [];
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('Request body must be a JSON object.');
  body = {};
}

const requiredText = function (obj, field, label) {
  const name = label || field;
  let v = obj[field];
  if (v === undefined || v === null) { errors.push(name + ' is required.'); return null; }
  if (typeof v === 'number' && (field.indexOf('_id') !== -1)) v = String(v);
  if (typeof v !== 'string') { errors.push(name + ' must be a string.'); return null; }
  const t = v.trim().replace(/\s+/g, ' ');
  if (t.length === 0) { errors.push(name + ' must not be empty.'); return null; }
  if (t.length > LIMITS[field]) { errors.push(name + ' must be at most ' + LIMITS[field] + ' characters.'); return null; }
  return t;
};

const customer_id = requiredText(body, 'customer_id');
const restaurant_id = requiredText(body, 'restaurant_id');
const delivery_address = requiredText(body, 'delivery_address');
const area_name = requiredText(body, 'area_name');
const payment_method = requiredText(body, 'payment_method');

let confirmationMissing = false;
if (body.customer_confirmed !== true) {
  confirmationMissing = true;
  errors.push('customer_confirmed must be the boolean true. The customer must explicitly confirm the final order summary and total before the order is processed.');
}

const items = [];
if (body.items === undefined || body.items === null) {
  errors.push('items is required.');
} else if (!Array.isArray(body.items)) {
  errors.push('items must be an array.');
} else if (body.items.length === 0) {
  errors.push('items must contain at least one item.');
} else if (body.items.length > MAX_ITEMS) {
  errors.push('items must contain at most ' + MAX_ITEMS + ' entries.');
} else {
  const seen = {};
  body.items.forEach(function (it, idx) {
    const label = 'items[' + idx + ']';
    if (!it || typeof it !== 'object' || Array.isArray(it)) { errors.push(label + ' must be an object.'); return; }
    const menu_item_id = requiredText(it, 'menu_item_id', label + '.menu_item_id');

    let quantity = null;
    const q = it.quantity;
    if (q === undefined || q === null || q === '') {
      errors.push(label + '.quantity is required.');
    } else if (typeof q === 'number' && Number.isInteger(q) && q >= 1) {
      quantity = q;
    } else if (typeof q === 'string' && /^[1-9][0-9]*$/.test(q.trim())) {
      quantity = Number(q.trim());
    } else {
      errors.push(label + '.quantity must be a positive whole number.');
    }
    if (quantity !== null && quantity > MAX_QTY) {
      errors.push(label + '.quantity must be at most ' + MAX_QTY + '.');
      quantity = null;
    }

    // Optional: only needed when the menu sheet stores several size prices on one row.
    let variant = null;
    if (it.variant !== undefined && it.variant !== null && it.variant !== '') {
      variant = requiredText(it, 'variant', label + '.variant');
    }

    if (menu_item_id !== null) {
      const key = menu_item_id + '|' + (variant || '').toLowerCase();
      if (seen[key]) {
        errors.push(label + ' repeats menu_item_id ' + menu_item_id + '. Combine the quantity into a single entry.');
      }
      seen[key] = true;
    }
    if (menu_item_id !== null && quantity !== null) {
      items.push({ menu_item_id: menu_item_id, quantity: quantity, variant: variant });
    }
  });
}

let discount = 0;
const d = body.discount;
if (d !== undefined && d !== null && d !== '') {
  const n = typeof d === 'number' ? d : (typeof d === 'string' && /^[0-9]+(\.[0-9]+)?$/.test(d.trim()) ? Number(d.trim()) : NaN);
  if (!Number.isFinite(n) || n < 0) errors.push('discount must be a non-negative number when provided.');
  else discount = Math.round(n * 100) / 100;
}

if (errors.length > 0) {
  const onlyConfirmation = confirmationMissing && errors.length === 1;
  return [{ json: {
    valid: false,
    statusCode: 400,
    body: {
      success: false,
      error: onlyConfirmation ? 'customer_confirmation_required' : 'invalid_request',
      message: onlyConfirmation
        ? 'The order was not processed because the customer has not explicitly confirmed it.'
        : 'Invalid order request: ' + errors.join(' '),
      details: errors,
    },
  } }];
}

return [{ json: {
  valid: true,
  request: {
    customer_id: customer_id,
    restaurant_id: restaurant_id,
    delivery_address: delivery_address,
    area_name: area_name,
    payment_method: payment_method,
    discount: discount,
    items: items,
  },
} }];

// Verifies every record against the sheets and calculates trusted totals.
// Read-only: nothing is written here. Output is either { ok: true, order, items }
// or { ok: false, statusCode, body } which goes straight to the webhook response.
try {
  const req = $('Validate Order Request').first().json.request;

  const fail = function (statusCode, error, message, extra) {
    return [{ json: { ok: false, statusCode: statusCode, body: Object.assign({ success: false, error: error, message: message }, extra || {}) } }];
  };

  const str = function (v) { return v === null || v === undefined ? '' : String(v).trim(); };
  const idKey = function (v) { return str(v).toUpperCase(); };
  const norm = function (v) { return str(v).replace(/\s+/g, ' ').toLowerCase(); };
  const isTrue = function (v) {
    if (v === true) return true;
    if (typeof v === 'number') return v === 1;
    if (typeof v !== 'string') return false;
    const s = v.trim().toLowerCase();
    return s === 'true' || s === 'yes' || s === 'y' || s === '1';
  };
  const toMoney = function (v) {
    if (v === null || v === undefined) return null;
    if (typeof v === 'number') return Number.isFinite(v) ? v : null;
    const s = String(v).trim().replace(/,/g, '').replace(/^(pkr|rs\.?)\s*/i, '');
    if (s === '' || !/^[0-9]+(\.[0-9]+)?$/.test(s)) return null;
    return Number(s);
  };
  const round2 = function (n) { return Math.round((n + Number.EPSILON) * 100) / 100; };

  const readSheet = function (nodeName) {
    const all = $(nodeName).all();
    if (all.some(function (i) { return i && i.json && i.json.error; })) return null;
    return all
      .map(function (i) { return i && i.json ? i.json : {}; })
      .filter(function (r) { return Object.keys(r).length > 0; });
  };

  const restaurants = readSheet('Read Restaurants');
  const menu = readSheet('Read Menu Items');
  const customers = readSheet('Read Customers');
  const zones = readSheet('Read Delivery Zones');
  if (!restaurants || !menu || !customers || !zones) {
    return fail(503, 'database_unavailable', 'The order database could not be read right now. No order was saved. Please try again shortly.');
  }

  const requireColumns = function (rows, cols, sheet) {
    const present = {};
    rows.forEach(function (r) { Object.keys(r).forEach(function (k) { present[k] = true; }); });
    const missing = cols.filter(function (c) { return !present[c]; });
    return missing.length ? 'The ' + sheet + ' sheet is missing required columns: ' + missing.join(', ') + '.' : null;
  };
  const colErr =
    requireColumns(customers, ['customer_id', 'customer_name', 'phone_number'], 'Customers') ||
    requireColumns(restaurants, ['restaurant_id', 'restaurant_name', 'is_active'], 'Restaurants') ||
    requireColumns(menu, ['menu_item_id', 'restaurant_id', 'item_name', 'is_available'], 'Menu_Items') ||
    requireColumns(zones, ['area_name', 'is_serviceable', 'delivery_fee'], 'Delivery_Zones');
  if (colErr) return fail(500, 'configuration_error', colErr + ' No order was saved.');

  // ---- Customer ----
  const custMatches = customers.filter(function (r) { return idKey(r.customer_id) === idKey(req.customer_id); });
  if (custMatches.length === 0) return fail(404, 'customer_not_found', 'No customer exists with customer_id ' + req.customer_id + '.');
  if (custMatches.length > 1) return fail(409, 'duplicate_customer_records', 'More than one customer row uses customer_id ' + req.customer_id + '. The Customers sheet must be corrected first.');
  const customer = custMatches[0];
  if (str(customer.customer_id) !== req.customer_id) {
    return fail(404, 'customer_not_found', 'customer_id ' + req.customer_id + ' does not exactly match a stored customer ID.');
  }

  // ---- Restaurant ----
  const restMatches = restaurants.filter(function (r) { return idKey(r.restaurant_id) === idKey(req.restaurant_id); });
  if (restMatches.length === 0) return fail(404, 'restaurant_not_found', 'No restaurant exists with restaurant_id ' + req.restaurant_id + '.');
  if (restMatches.length > 1) return fail(409, 'duplicate_restaurant_records', 'More than one restaurant row uses restaurant_id ' + req.restaurant_id + '. The Restaurants sheet must be corrected first.');
  const restaurant = restMatches[0];
  if (!isTrue(restaurant.is_active)) {
    return fail(422, 'restaurant_unavailable', str(restaurant.restaurant_name) + ' is not currently accepting orders.');
  }
  // Opening hours (Asia/Karachi, UTC+5, no DST). Checked only when both times are present and parseable.
  const parseTime = function (v) {
    const m = /^([0-9]{1,2}):([0-9]{2})/.exec(str(v));
    if (!m) return null;
    const h = Number(m[1]), mi = Number(m[2]);
    return h <= 24 && mi < 60 ? (h * 60 + mi) % 1440 : null;
  };
  const openM = parseTime(restaurant.opening_time);
  const closeM = parseTime(restaurant.closing_time);
  if (openM !== null && closeM !== null && openM !== closeM) {
    const now = new Date();
    const nowM = (now.getUTCHours() * 60 + now.getUTCMinutes() + 300) % 1440;
    const isOpen = openM < closeM ? (nowM >= openM && nowM < closeM) : (nowM >= openM || nowM < closeM);
    if (!isOpen) {
      return fail(422, 'restaurant_closed', str(restaurant.restaurant_name) + ' is closed right now (hours ' + str(restaurant.opening_time) + ' to ' + str(restaurant.closing_time) + ', Karachi time).');
    }
  }

  // ---- Menu items ----
  // Price columns other than "price" (e.g. price_half / full_price) mean the row stores several size prices.
  const variantPriceCols = function (row) {
    return Object.keys(row).filter(function (k) {
      return k !== 'price' && /price/i.test(k) && toMoney(row[k]) !== null && str(row[k]) !== '';
    });
  };

  const lines = [];
  for (let i = 0; i < req.items.length; i++) {
    const want = req.items[i];
    const rows = menu.filter(function (r) { return idKey(r.menu_item_id) === idKey(want.menu_item_id); });
    if (rows.length === 0) return fail(404, 'menu_item_not_found', 'Menu item ' + want.menu_item_id + ' does not exist.', { menu_item_id: want.menu_item_id });
    if (rows.length > 1) return fail(409, 'ambiguous_menu_item', 'Menu item ID ' + want.menu_item_id + ' appears on more than one row, so the exact item and price cannot be determined.', { menu_item_id: want.menu_item_id });
    const m = rows[0];
    const itemName = str(m.item_name);
    if (idKey(m.restaurant_id) !== idKey(restaurant.restaurant_id)) {
      return fail(422, 'item_not_from_restaurant', (itemName || want.menu_item_id) + ' (' + want.menu_item_id + ') does not belong to ' + str(restaurant.restaurant_name) + '.', { menu_item_id: want.menu_item_id });
    }
    if (!isTrue(m.is_available)) {
      return fail(422, 'item_unavailable', (itemName || want.menu_item_id) + ' (' + want.menu_item_id + ') is not currently available.', { menu_item_id: want.menu_item_id });
    }
    if (!itemName) return fail(500, 'configuration_error', 'Menu item ' + want.menu_item_id + ' has no item_name. No order was saved.');

    let unitPrice = null;
    let variantLabel = str(m.serving_size);
    const extraCols = variantPriceCols(m);
    const basePrice = str(m.price) === '' ? null : toMoney(m.price);

    if (extraCols.length === 0) {
      // One row = one variant (e.g. separate half/full rows). Use the row price.
      if (want.variant && variantLabel && norm(want.variant) !== norm(variantLabel)) {
        return fail(422, 'variant_mismatch', 'The requested size "' + want.variant + '" does not match ' + itemName + ' (' + want.menu_item_id + '), which is "' + variantLabel + '". Send the menu_item_id of the size the customer selected.', { menu_item_id: want.menu_item_id });
      }
      unitPrice = basePrice;
    } else {
      // Several size prices on one row: resolve only from an explicit, matching variant.
      if (!want.variant) {
        return fail(422, 'variant_required', itemName + ' (' + want.menu_item_id + ') has multiple size prices (' + extraCols.join(', ') + '). The selected size must be supplied; it will not be guessed.', { menu_item_id: want.menu_item_id });
      }
      const token = norm(want.variant).replace(/[^a-z0-9]+/g, '');
      const hits = extraCols.filter(function (k) {
        return k.toLowerCase().split(/[^a-z0-9]+/).indexOf(token) !== -1;
      });
      if (hits.length !== 1) {
        return fail(422, 'ambiguous_variant', 'The size "' + want.variant + '" could not be matched to exactly one price for ' + itemName + ' (' + want.menu_item_id + ').', { menu_item_id: want.menu_item_id });
      }
      unitPrice = toMoney(m[hits[0]]);
      variantLabel = want.variant;
    }
    if (unitPrice === null || !(unitPrice > 0)) {
      return fail(422, 'invalid_item_price', itemName + ' (' + want.menu_item_id + ') has no valid price in the menu, so it cannot be ordered.', { menu_item_id: want.menu_item_id });
    }
    unitPrice = round2(unitPrice);
    lines.push({
      menu_item_id: str(m.menu_item_id),
      item_name: itemName,
      variant: variantLabel,
      quantity: want.quantity,
      unit_price: unitPrice,
      line_total: round2(unitPrice * want.quantity),
    });
  }

  // ---- Delivery zone ----
  const zoneMatches = zones.filter(function (z) { return norm(z.area_name) === norm(req.area_name); });
  if (zoneMatches.length === 0) return fail(422, 'area_not_serviceable', 'We do not deliver to "' + req.area_name + '".', { area_name: req.area_name });
  if (zoneMatches.length > 1) return fail(409, 'ambiguous_delivery_zone', 'More than one delivery zone matches "' + req.area_name + '". The Delivery_Zones sheet must be corrected first.', { area_name: req.area_name });
  const zone = zoneMatches[0];
  if (!isTrue(zone.is_serviceable)) return fail(422, 'area_not_serviceable', 'Delivery is currently not available in ' + str(zone.area_name) + '.', { area_name: str(zone.area_name) });
  const fee = str(zone.delivery_fee) === '' ? null : toMoney(zone.delivery_fee);
  if (fee === null || fee < 0) return fail(500, 'configuration_error', 'The delivery fee for ' + str(zone.area_name) + ' is missing or invalid. No order was saved.');

  // ---- Totals ----
  const itemsSubtotal = round2(lines.reduce(function (s, l) { return s + l.line_total; }, 0));
  const deliveryFee = round2(fee);
  const discount = round2(req.discount);
  if (discount > itemsSubtotal) {
    return fail(422, 'invalid_discount', 'The discount (' + discount + ') cannot exceed the items subtotal (' + itemsSubtotal + ').');
  }
  const minOrder = str(restaurant.minimum_order) === '' ? null : toMoney(restaurant.minimum_order);
  if (minOrder !== null && itemsSubtotal < minOrder) {
    return fail(422, 'below_minimum_order', 'The items subtotal (' + itemsSubtotal + ') is below the minimum order of ' + minOrder + ' for ' + str(restaurant.restaurant_name) + '.');
  }
  const totalAmount = round2(itemsSubtotal + deliveryFee - discount);

  // ---- IDs ----
  const now = new Date();
  const ts = now.toISOString().replace(/[-:TZ.]/g, '').slice(0, 14);
  const rand = (Math.random().toString(36).slice(2) + '000000').slice(0, 6).toUpperCase();
  const orderId = 'ORD' + ts + rand;

  const items = lines.map(function (l, idx) {
    return Object.assign({ order_item_id: orderId + '-' + String(idx + 1).padStart(2, '0'), order_id: orderId }, l);
  });

  return [{ json: {
    ok: true,
    order: {
      order_id: orderId,
      customer_id: str(customer.customer_id),
      customer_name: str(customer.customer_name),
      phone_number: str(customer.phone_number),
      restaurant_id: str(restaurant.restaurant_id),
      restaurant_name: str(restaurant.restaurant_name),
      delivery_address: req.delivery_address,
      area_name: str(zone.area_name),
      items_subtotal: itemsSubtotal,
      delivery_fee: deliveryFee,
      discount: discount,
      total_amount: totalAmount,
      payment_method: req.payment_method,
      order_status: 'Pending',
      created_at: now.toISOString(),
    },
    items: items,
  } }];
} catch (err) {
  return [{ json: { ok: false, statusCode: 500, body: {
    success: false, error: 'internal_error', message: 'Something went wrong while verifying the order. No order was saved.',
  } } }];
}

// Runs only after the Orders row was appended successfully. Emits one item per order line.
const v = $('Verify Order & Calculate Totals').first().json;
return v.items.map(function (it) {
  return { json: {
    order_item_id: it.order_item_id,
    order_id: it.order_id,
    menu_item_id: it.menu_item_id,
    item_name: it.item_name,
    quantity: it.quantity,
    unit_price: it.unit_price,
    line_total: it.line_total,
  } };
});

// Confirms every Order_Items row was written. Reports an explicit partial failure otherwise.
try {
  const v = $('Verify Order & Calculate Totals').first().json;
  const order = v.order;
  const expected = v.items;
  const results = $input.all().map(function (i) { return i && i.json ? i.json : {}; });

  const writtenIds = {};
  results.forEach(function (r) {
    if (r && !r.error && r.order_item_id !== undefined) writtenIds[String(r.order_item_id).trim()] = true;
  });
  const missing = expected.filter(function (it) { return !writtenIds[it.order_item_id]; });
  const hadError = results.some(function (r) { return r && r.error; });

  if (hadError || missing.length > 0) {
    return [{ json: { statusCode: 500, body: {
      success: false,
      error: 'partial_order_write',
      message: 'Order ' + order.order_id + ' was saved, but some of its items could not be confirmed as saved. The order is incomplete and must be reviewed manually. Do not resubmit it automatically, as that would create a duplicate order.',
      order_id: order.order_id,
      unconfirmed_order_item_ids: missing.map(function (it) { return it.order_item_id; }),
    } } }];
  }

  return [{ json: { statusCode: 201, body: {
    success: true,
    message: 'Order ' + order.order_id + ' was created and is ' + order.order_status + '.',
    order_id: order.order_id,
    order: {
      order_id: order.order_id,
      order_status: order.order_status,
      created_at: order.created_at,
      customer_id: order.customer_id,
      customer_name: order.customer_name,
      restaurant_id: order.restaurant_id,
      restaurant_name: order.restaurant_name,
      delivery_address: order.delivery_address,
      area_name: order.area_name,
      payment_method: order.payment_method,
      items: expected.map(function (it) {
        return {
          order_item_id: it.order_item_id,
          menu_item_id: it.menu_item_id,
          item_name: it.item_name,
          variant: it.variant,
          quantity: it.quantity,
          unit_price: it.unit_price,
          line_total: it.line_total,
        };
      }),
      items_subtotal: order.items_subtotal,
      delivery_fee: order.delivery_fee,
      discount: order.discount,
      total_amount: order.total_amount,
      currency: 'PKR',
    },
  } } }];
} catch (err) {
  let orderId = null;
  try { orderId = $('Verify Order & Calculate Totals').first().json.order.order_id; } catch (e) { orderId = null; }
  return [{ json: { statusCode: 500, body: {
    success: false,
    error: 'order_status_unknown',
    message: 'The order may have been partly saved but could not be confirmed. Review it manually and do not resubmit automatically.',
    order_id: orderId,
  } } }];
}

// Append Order failed: no item rows are written. The order row cannot be confirmed either way.
let orderId = null;
try { orderId = $('Verify Order & Calculate Totals').first().json.order.order_id; } catch (e) { orderId = null; }
return [{ json: { statusCode: 503, body: {
  success: false,
  error: 'order_write_failed',
  message: 'The order could not be saved to the database, so no order items were written. Check the Orders sheet for this order ID before trying again, so a duplicate order is not created.',
  order_id: orderId,
} } }];
